WITH scored AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY sale_date, id) AS event_seq, NTILE(4) OVER (PARTITION BY DATE_TRUNC('YEAR', sale_date), product_id ORDER BY revenue, id) AS revenue_bucket FROM store_sales WHERE product_id IN (4, 6, 8)), cleaned AS (SELECT id, store_id, product_id, sale_date, revenue, event_seq, revenue_bucket, ROUND(revenue / event_seq, 2) AS revenue_per_event_seq FROM scored WHERE sale_date > DATE '2023-10-05'), joined AS (SELECT a.id, a.store_id, a.product_id, a.revenue, a.revenue_bucket, b.city, b.store_name, b.region FROM cleaned a JOIN stores b ON a.store_id = b.id), scored_store_sales AS (SELECT *, ROUND(revenue_bucket / SUM(revenue_bucket) OVER (PARTITION BY product_id), 4) AS revenue_bucket_share, SUM(revenue) OVER (PARTITION BY region ORDER BY revenue_bucket, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_revenue, FIRST_VALUE(region, TRUE) OVER (PARTITION BY store_id ORDER BY revenue_bucket, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_region, ROW_NUMBER() OVER (PARTITION BY city ORDER BY revenue DESC, id) AS event_seq FROM joined), joined_store_sales AS (SELECT s.*, b.category, b.launch_date FROM scored_store_sales s JOIN products b ON s.product_id = b.id), metrics AS (SELECT *, LAG(revenue_bucket_share) OVER w_grp AS prev_revenue_bucket_share, LEAD(revenue_bucket_share) OVER w_grp AS next_revenue_bucket_share, LEAD(cumulative_revenue) OVER w_grp AS next_cumulative_revenue, LAG(cumulative_revenue) OVER w_grp AS prev_cumulative_revenue, ROW_NUMBER() OVER w_grp AS event_seq_2, ROW_NUMBER() OVER (PARTITION BY YEAR(launch_date), city ORDER BY revenue_bucket DESC, id) AS row_seq FROM joined_store_sales WINDOW w_grp AS (PARTITION BY product_id ORDER BY revenue_bucket, id)) SELECT *, LEAD(prev_cumulative_revenue) OVER (PARTITION BY region, city ORDER BY prev_cumulative_revenue, id) AS next_prev_cumulative_revenue, LEAD(cumulative_revenue) OVER (PARTITION BY region, city ORDER BY prev_cumulative_revenue, id) AS next_cumulative_revenue_2, ROW_NUMBER() OVER (PARTITION BY region, city ORDER BY prev_cumulative_revenue, id) AS event_seq_3, ROUND(event_seq_2 / SUM(event_seq_2) OVER (PARTITION BY store_id), 4) AS event_seq_2_share FROM metrics
